namespace RonSijm.FluidHumidifier.Factories.AIOps;

public class InvestigationGroupFactory(string resourceName = null, Action<Humidifier.AIOps.InvestigationGroup> factoryAction = null) : ResourceFactory<Humidifier.AIOps.InvestigationGroup>(resourceName)
{

    internal List<InnerInvestigationGroupCrossAccountConfigurationFactory> CrossAccountConfigurationsFactories { get; set; } = [];

    internal List<InnerInvestigationGroupChatbotNotificationChannelFactory> ChatbotNotificationChannelsFactories { get; set; } = [];

    internal InnerInvestigationGroupEncryptionConfigMapFactory EncryptionConfigFactory { get; set; }

    protected override Humidifier.AIOps.InvestigationGroup Create()
    {
        var investigationGroupResult = CreateInvestigationGroup();
        factoryAction?.Invoke(investigationGroupResult);

        return investigationGroupResult;
    }

    private Humidifier.AIOps.InvestigationGroup CreateInvestigationGroup()
    {
        var investigationGroupResult = new Humidifier.AIOps.InvestigationGroup
        {
            GivenName = InputResourceName,
        };

        return investigationGroupResult;
    }
    public override void CreateChildren(Humidifier.AIOps.InvestigationGroup result)
    {
        base.CreateChildren(result);

        result.CrossAccountConfigurations = CrossAccountConfigurationsFactories.Any() ? CrossAccountConfigurationsFactories.Select(x => x.Build()).ToList() : null;
        result.ChatbotNotificationChannels = ChatbotNotificationChannelsFactories.Any() ? ChatbotNotificationChannelsFactories.Select(x => x.Build()).ToList() : null;
        result.EncryptionConfig ??= EncryptionConfigFactory?.Build();
    }

} // End Of Class

